<template>
  <div ref="shell" class="lab3d-shell">
    <header class="scene-toolbar">
      <div class="toolbar-card location-card">
        <div class="scene-identity">
          <span class="identity-icon"><EnvironmentOutlined /></span>
          <div><small>{{ roomMode ? '当前房间' : '实验室空间总览' }}</small><strong>{{ currentRoom?.name || currentLab?.name || scenes[0]?.sceneName || '实验室空间' }}</strong></div>
        </div>
        <a-button v-if="currentRoom" class="back-button" @click="showLab(sceneId)"><ArrowLeftOutlined />返回楼层</a-button>
        <a-select v-else v-model:value="sceneId" class="scene-select" :options="sceneOptions" @change="loadScene" />
      </div>
      <div class="toolbar-card toolbar-actions">
        <div class="view-switch" aria-label="空间视图模式">
          <button :class="{ active: !is2d }" @click="is2d=false">3D</button>
          <button :class="{ active: is2d }" @click="is2d=true">2D</button>
        </div>
        <span class="action-divider" />
        <a-tooltip title="复位视角"><a-button aria-label="复位视角" @click="resetCamera"><ReloadOutlined /></a-button></a-tooltip>
        <a-tooltip title="全屏"><a-button aria-label="全屏" @click="toggleFullscreen"><FullscreenOutlined /></a-button></a-tooltip>
      </div>
      <div class="toolbar-card space-metrics">
        <span><i class="metric-dot is-normal" /><small>房间</small><b>{{ visibleRoomCount }}</b></span>
        <span><i class="metric-dot is-normal" /><small>仪器</small><b>{{ visibleInstrumentCount }}</b></span>
        <span class="metric-repair"><i class="metric-dot is-repair" /><small>维修</small><b>{{ visibleRepairCount }}</b></span>
      </div>
    </header>

    <div class="space-workbench">
      <aside class="space-index">
        <div class="index-heading"><div><small>{{ currentRoom?.floorName || (demoMode?'DEMO SPACE':currentLab?.code) }}</small><strong>{{ roomMode ? '房间设备' : '楼层导航' }}</strong></div><a-tag :color="demoMode?'blue':'green'">{{ demoMode?'模拟':'实时' }}</a-tag></div>
        <div class="index-tools">
          <a-input-search v-model:value="keyword" class="scene-search" allow-clear placeholder="搜索房间、编号或仪器" @search="focusSearch" />
          <div v-if="!roomMode && floorOptions.length > 1" class="floor-navigation">
            <button v-for="option in floorOptions" :key="option.value" :class="{ active: floorFilter===option.value }" @click="floorFilter=option.value">
              <span>{{ option.value ? `${option.value}F` : '全' }}</span>
              <div><strong>{{ option.label }}</strong><small>{{ option.value ? `${nodes.filter(node=>node.floor===option.value).length} 个房间` : `${visibleRoomCount} 个房间` }}</small></div>
            </button>
          </div>
          <div class="status-filter"><span>运行状态</span><a-segmented v-model:value="statusFilter" :options="statusOptions" block /></div>
        </div>
      <div class="index-scroll">
        <section v-for="group in groupedNodes" :key="group.floor" class="floor-group">
          <div v-if="!roomMode" class="floor-heading"><span>{{ group.floor }}F</span><div><b>{{ group.floor }} 层</b><small>{{ group.nodes.length }} 个房间</small></div></div>
          <button v-for="node in group.nodes" :key="node.id" class="index-node" @click="selectNode(node)">
            <i :class="`is-${node.status}`" /><span><b>{{ node.name }}</b><small>{{ node.code }} · {{ nodeSummary(node) }}</small></span><RightOutlined />
          </button>
        </section>
        <a-empty v-if="!filteredNodes.length" :description="currentRoom?'该房间暂无已录入仪器':'没有符合条件的房间'" />
      </div>
      </aside>

      <main class="scene-panel">
        <div class="scene-caption">
          <div><small>{{ is2d ? '二维平面视图' : '三维空间模型' }}</small><strong>{{ floorFilter ? `${floorFilter}F · ${floorFilter} 层空间` : (currentRoom?.fullPath || '全部楼层') }}</strong></div>
          <span><i :class="demoMode?'is-demo':'is-live'" />{{ demoMode?'模拟数据':'数据已同步' }}</span>
        </div>
        <div v-show="!is2d" ref="canvasHost" class="canvas-host" />
        <div v-if="is2d" class="fallback-view">
          <section v-for="group in groupedNodes" :key="group.floor" class="fallback-floor">
            <div class="fallback-heading">
              <span>{{ group.floor }}F</span>
              <div><small>{{ roomMode ? 'ROOM VIEW' : 'FLOOR PLAN' }}</small><strong>{{ roomMode ? (currentRoom?.name||'模拟实验室') : `${group.floor} 层空间` }}</strong><p>{{ group.nodes.length }} 个{{ roomMode?'设备':'房间' }}</p></div>
            </div>
            <div class="fallback-grid" :class="{ 'is-equipment': roomMode }">
              <button v-for="node in group.nodes" :key="node.id" class="fallback-node" :class="`status-${node.status}`" @click="selectNode(node)">
                <span class="node-accent" />
                <div class="node-card-head"><span class="node-code">{{ node.code }}</span><span class="node-state"><i :class="`is-${node.status}`" />{{ statusText[node.status]||node.status }}</span></div>
                <strong>{{ node.name }}</strong>
                <small class="node-location">{{ node.detail||'暂无位置说明' }}</small>
                <div class="node-card-foot">
                  <template v-if="node.type==='room'"><span><CalendarOutlined />{{ node.upcomingBookingCount||0 }} 个预约</span><span><ToolOutlined />{{ node.repairingInstrumentCount||0 }} 台维修</span></template>
                  <template v-else><span><ExperimentOutlined />仪器设备</span><span v-if="node.nextBookingTime"><CalendarOutlined />{{ formatShortTime(node.nextBookingTime) }}</span></template>
                  <RightOutlined class="node-arrow" />
                </div>
              </button>
            </div>
          </section>
          <a-empty v-if="!filteredNodes.length" description="没有符合条件的空间数据" />
        </div>
        <div class="scene-legend"><span><i class="is-normal"/>正常</span><span><i class="is-repair"/>维修</span><span><i class="is-stopped"/>停用</span><span><i class="is-unknown"/>未知</span></div>
      </main>

      <aside class="node-panel">
        <template v-if="selected">
          <div class="panel-head"><div><small>{{ selected.type==='room'?'ROOM':'INSTRUMENT' }}</small><strong>节点详情</strong></div><button aria-label="关闭详情" @click="selected=null"><CloseOutlined /></button></div>
          <span class="panel-code">{{ selected.code }}</span><h2>{{ selected.name }}</h2>
          <div class="status-line"><span :class="`status-dot is-${selected.status}`" />{{ statusText[selected.status]||selected.status }}</div>
          <div class="panel-metrics"><div><small>待执行预约</small><b>{{ selected.upcomingBookingCount||0 }}</b></div><div><small>维修中设备</small><b>{{ selected.repairingInstrumentCount||0 }}</b></div></div>
          <div class="detail-section"><h3>基础信息</h3><dl><dt>节点类型</dt><dd>{{ selected.type==='room'?'实验室房间':'仪器设备' }}</dd><dt>位置</dt><dd>{{ selected.detail||'未绑定业务数据' }}</dd><template v-if="selected.nextBookingTime"><dt>最近预约</dt><dd>{{ formatTime(selected.nextBookingTime) }}</dd></template></dl></div>
        </template>
        <template v-else-if="currentRoom">
          <div class="panel-head"><div><small>ROOM OVERVIEW</small><strong>房间概况</strong></div></div>
          <span class="panel-code">{{ currentRoom.code }}</span><h2>{{ currentRoom.name }}</h2>
          <div class="status-line"><span class="status-dot is-normal" />空间数据已同步</div>
          <div class="panel-metrics"><div><small>仪器设备</small><b>{{ currentRoom.instruments.length }}</b></div><div><small>待执行预约</small><b>{{ currentRoom.upcomingBookingCount }}</b></div></div>
          <div class="detail-section"><h3>空间信息</h3><dl><dt>所在楼层</dt><dd>{{ currentRoom.floorName }}</dd><dt>完整位置</dt><dd>{{ currentRoom.fullPath }}</dd><dt>维修设备</dt><dd>{{ currentRoom.repairingInstrumentCount }} 台</dd></dl></div>
        </template>
        <template v-else>
          <div class="panel-head"><div><small>SPACE OVERVIEW</small><strong>空间概况</strong></div></div>
          <span class="panel-code">{{ demoMode?'DEMO':currentLab?.code||'LAB' }}</span><h2>{{ currentLab?.name || scenes[0]?.sceneName || '实验室空间' }}</h2>
          <div class="status-line"><span :class="`status-dot ${demoMode?'is-unknown':'is-normal'}`" />{{ demoMode?'模拟空间数据':'空间数据已同步' }}</div>
          <div class="panel-metrics"><div><small>楼层数量</small><b>{{ Math.max(floorOptions.length-1,1) }}</b></div><div><small>房间数量</small><b>{{ visibleRoomCount }}</b></div><div><small>仪器设备</small><b>{{ visibleInstrumentCount }}</b></div><div><small>维修设备</small><b class="repair-value">{{ visibleRepairCount }}</b></div></div>
          <div class="detail-section"><h3>运行信息</h3><dl><dt>当前范围</dt><dd>{{ floorFilter?`${floorFilter} 层`:'全部楼层' }}</dd><dt>数据来源</dt><dd>{{ demoMode?'本地模拟数据':'实验室基础数据' }}</dd><dt>刷新频率</dt><dd>每 15 秒</dd></dl></div>
        </template>
      </aside>
    </div>

    <div v-if="loading" class="scene-loading"><a-spin size="large" /><span>正在构建实验室空间</span></div>
  </div>
</template>

<script setup lang="ts">
import { CSS2DObject, CSS2DRenderer } from 'three/examples/jsm/renderers/CSS2DRenderer.js';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { ArrowLeftOutlined, CalendarOutlined, CloseOutlined, EnvironmentOutlined, ExperimentOutlined, FullscreenOutlined, ReloadOutlined, RightOutlined, ToolOutlined } from '@ant-design/icons-vue';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { visualizationApi } from '../../api/visualization';
import type { Lab3dNode, Lab3dScene, LabSpatialLab, LabSpatialRoom } from '../../types/visualization';

const shell=ref<HTMLElement>(),canvasHost=ref<HTMLElement>();
const scenes=ref<Lab3dScene[]>([]),spatialLabs=ref<LabSpatialLab[]>([]),sceneId=ref(''),nodes=ref<Lab3dNode[]>([]),currentRoom=ref<LabSpatialRoom|null>(null),selected=ref<Lab3dNode|null>(null);
const keyword=ref(''),statusFilter=ref('all'),floorFilter=ref(0),is2d=ref(false),loading=ref(false),demoMode=ref(false);
const statusText:Record<string,string>={normal:'正常',repair:'维修中',repairing:'维修中',stopped:'已停用',unknown:'未知'};
const statusOptions=[{label:'全部',value:'all'},{label:'正常',value:'normal'},{label:'维修',value:'repair'},{label:'停用',value:'stopped'}];
const sceneOptions=computed(()=>scenes.value.map(x=>({label:x.sceneName,value:x.id})));
const currentLab=computed(()=>spatialLabs.value.find(x=>x.id===sceneId.value));
const roomMode=computed(()=>!!currentRoom.value||demoMode.value);
const floorOptions=computed(()=>[{label:'全部楼层',value:0},...Array.from(new Set(nodes.value.map(x=>x.floor).filter((x):x is number=>!!x))).sort((a,b)=>a-b).map(x=>({label:`${x} 层`,value:x}))]);
const filteredNodes=computed(()=>nodes.value.filter(x=>(!floorFilter.value||x.floor===floorFilter.value)&&(statusFilter.value==='all'||x.status===statusFilter.value)&&(!keyword.value||`${x.name}${x.code}${x.detail||''}`.toLowerCase().includes(keyword.value.toLowerCase()))));
const groupedNodes=computed(()=>{const groups=new Map<number,Lab3dNode[]>();for(const node of filteredNodes.value){const floor=node.floor||currentRoom.value?.floorNumber||1;groups.set(floor,[...(groups.get(floor)||[]),node]);}return [...groups].sort(([a],[b])=>a-b).map(([floor,items])=>({floor,nodes:items}));});
const visibleRooms=computed(()=>currentLab.value?.rooms.filter(x=>!floorFilter.value||x.floorNumber===floorFilter.value)||[]);
const visibleRoomCount=computed(()=>roomMode.value?1:visibleRooms.value.length);
const visibleInstrumentCount=computed(()=>demoMode.value?filteredNodes.value.length:currentRoom.value?currentRoom.value.instruments.length:visibleRooms.value.reduce((sum,x)=>sum+x.instruments.length,0));
const visibleRepairCount=computed(()=>demoMode.value?filteredNodes.value.filter(x=>['repair','repairing'].includes(x.status)).length:currentRoom.value?currentRoom.value.instruments.filter(x=>['repair','repairing'].includes(x.status)).length:visibleRooms.value.reduce((sum,x)=>sum+x.repairingInstrumentCount,0));

let renderer:THREE.WebGLRenderer|undefined,labelRenderer:CSS2DRenderer|undefined,scene:THREE.Scene|undefined,camera:THREE.PerspectiveCamera|undefined,controls:OrbitControls|undefined,frame=0,timer=0,darkScene=false;
const meshes=new Map<string,THREE.Mesh>(),floorObjects=new Map<number,THREE.Object3D>(),raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();

onMounted(async()=>{loading.value=true;if(window.location.pathname==='/__lab3d-preview'){await loadDemo();loading.value=false;return;}try{spatialLabs.value=await visualizationApi.layout();if(spatialLabs.value.length){scenes.value=spatialLabs.value.map(x=>({id:x.id,labId:x.id,labName:x.name,sceneName:x.name,backgroundColor:'#e9f0f2',version:1,isActive:true}));sceneId.value=scenes.value[0].id;await showLab(sceneId.value);}else await loadDemo();}catch{await loadDemo();}finally{loading.value=false;}timer=window.setInterval(refreshStatuses,15000);});
onBeforeUnmount(dispose);
watch([statusFilter,keyword,floorFilter],applyVisibility);
watch(is2d,async value=>{await nextTick();if(!value){resize();resetCamera();if(renderer&&scene&&camera)renderer.render(scene,camera);}});

async function loadScene(){if(spatialLabs.value.length){await showLab(sceneId.value);return;}if(!sceneId.value)return;loading.value=true;try{const data=await visualizationApi.scene(sceneId.value);if(!data.nodes?.length){await loadDemo();return;}demoMode.value=false;nodes.value=data.nodes;await nextTick();build(data.scene.backgroundColor,data.scene.modelUrl);}catch{await loadDemo();}finally{loading.value=false;}}
async function showLab(id:string){const lab=spatialLabs.value.find(x=>x.id===id);if(!lab)return;currentRoom.value=null;selected.value=null;floorFilter.value=0;demoMode.value=false;const indexes=new Map<number,number>(),counts=new Map<number,number>();lab.rooms.forEach(x=>counts.set(x.floorNumber,(counts.get(x.floorNumber)||0)+1));nodes.value=lab.rooms.map(room=>{const floor=room.floorNumber||1,index=indexes.get(floor)||0,count=counts.get(floor)||1;indexes.set(floor,index+1);const columns=Math.min(count,3),row=Math.floor(index/columns),column=index%columns;return{id:room.id,code:room.code,name:room.name,type:'room',floor,x:(column-(columns-1)/2)*4.6,y:(floor-1)*3.2+.72,z:row*2.5-.35,scaleX:2.15,scaleY:1.15,scaleZ:1.55,businessType:'room',businessId:room.id,status:room.repairingInstrumentCount?'repair':room.instruments.some(x=>x.status==='stopped')?'stopped':'normal',detail:`${room.fullPath} · ${room.instruments.length} 台仪器`,upcomingBookingCount:room.upcomingBookingCount,repairingInstrumentCount:room.repairingInstrumentCount,nextBookingTime:room.instruments.map(x=>x.nextBookingTime).filter(Boolean).sort()[0]};});await nextTick();build('#e9f0f2');}
async function enterRoom(room:LabSpatialRoom){currentRoom.value=room;selected.value=null;floorFilter.value=0;nodes.value=room.instruments.map((x,i)=>({id:x.id,code:x.code,name:x.name,type:'instrument',floor:room.floorNumber,x:(i%4)*3.25-4.9,y:.88,z:Math.floor(i/4)*3.5-2,scaleX:1,scaleY:1,scaleZ:1,businessType:'instrument',businessId:x.id,status:x.status,detail:`${room.fullPath} / ${x.locationName}${x.model?` · ${x.model}`:''}`,upcomingBookingCount:x.upcomingBookingCount,repairingInstrumentCount:x.repairStatus?1:0,nextBookingTime:x.nextBookingTime}));await nextTick();build('#e9f0f2');}
async function loadDemo(){demoMode.value=true;const demo:Lab3dScene={id:'demo',labId:'demo',labName:'中心实验室',sceneName:'中心实验室模拟空间',backgroundColor:'#e9f0f2',version:1,isActive:true};scenes.value=[demo];sceneId.value=demo.id;const names=['气相色谱仪','液相色谱仪','紫外分光光度计','高速离心机','超低温冰箱','生物安全柜','电子分析天平','恒温培养箱'];nodes.value=names.map((name,i)=>({id:`demo-${i}`,code:`LAB-${String(i+1).padStart(2,'0')}`,name,type:'instrument',floor:1,x:(i%4)*3.25-4.9,y:.88,z:Math.floor(i/4)*3.5-2,scaleX:1,scaleY:1,scaleZ:1,businessType:'instrument',businessId:`demo-${i}`,status:i===1?'repair':i===4?'stopped':'normal',detail:'模拟设备数据',upcomingBookingCount:i%3,repairingInstrumentCount:i===1?1:0}));await nextTick();build(demo.backgroundColor);}

function build(background:string,modelUrl?:string){disposeRenderer();const host=canvasHost.value;if(!host)return;darkScene=['personal','neo'].includes(document.documentElement.dataset.theme||'');const sceneBackground=darkScene?'#111a1c':background;scene=new THREE.Scene();scene.background=new THREE.Color(sceneBackground);scene.fog=new THREE.Fog(sceneBackground,20,45);camera=new THREE.PerspectiveCamera(46,host.clientWidth/Math.max(host.clientHeight,1),.1,100);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(host.clientWidth,host.clientHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFShadowMap;labelRenderer=new CSS2DRenderer();labelRenderer.setSize(host.clientWidth,host.clientHeight);Object.assign(labelRenderer.domElement.style,{position:'absolute',inset:'0',pointerEvents:'none'});host.replaceChildren(renderer.domElement,labelRenderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.48;controls.minDistance=6;controls.maxDistance=38;scene.add(new THREE.HemisphereLight(0xffffff,darkScene?0x18363a:0x52636d,darkScene?1.75:2.3));const sun=new THREE.DirectionalLight(0xffffff,darkScene?2.5:3.2);sun.position.set(7,14,10);sun.castShadow=true;scene.add(sun);const ground=new THREE.Mesh(new THREE.PlaneGeometry(28,20),new THREE.MeshStandardMaterial({color:darkScene?0x1d2b2e:0xdfe7e9,roughness:.9}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);const grid=new THREE.GridHelper(28,28,darkScene?0x4d7778:0xb1c0c4,darkScene?0x293d40:0xd0dadd);grid.position.y=.01;scene.add(grid);if(currentRoom.value||demoMode.value)addRoom();else addBuilding();meshes.clear();nodes.value.forEach(addNode);if(modelUrl)new GLTFLoader().load(modelUrl,g=>scene?.add(g.scene),undefined,()=>{});renderer.domElement.addEventListener('pointerdown',pick);window.addEventListener('resize',resize);resetCamera();animate();applyVisibility();}
function addNode(node:Lab3dNode){if(!scene)return;const mesh=new THREE.Mesh(new THREE.BoxGeometry(1.35,1.25,1.35),new THREE.MeshStandardMaterial({color:colorFor(node.status),roughness:.36,metalness:.12}));mesh.position.set(node.x,node.y,node.z);mesh.scale.set(node.scaleX,node.scaleY,node.scaleZ);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.nodeId=node.id;const element=document.createElement('div');element.className='node-label';element.innerHTML=`<b>${escapeHtml(node.name)}</b><span>${escapeHtml(node.code)}</span>`;const label=new CSS2DObject(element);label.position.set(0,node.type==='room'?1.2:1.05,0);mesh.add(label);scene.add(mesh);meshes.set(node.id,mesh);}
function addBuilding(){if(!scene)return;floorObjects.clear();const floors=Array.from(new Set(nodes.value.map(x=>x.floor||1))).sort((a,b)=>a-b),maxFloor=Math.max(...floors);const slabColors=darkScene?[0x314548,0x2b3e41,0x26383b]:[0xd9e4e6,0xd1dddf,0xc9d6d9];for(const floor of floors){const group=new THREE.Group(),y=(floor-1)*3.2;const slab=new THREE.Mesh(new THREE.BoxGeometry(15,.2,7),new THREE.MeshStandardMaterial({color:slabColors[(floor-1)%slabColors.length],roughness:.78}));slab.position.y=y;slab.receiveShadow=true;group.add(slab);const back=new THREE.Mesh(new THREE.BoxGeometry(15,2.75,.12),new THREE.MeshStandardMaterial({color:darkScene?0x30464a:0xf3f7f7,transparent:true,opacity:darkScene?.82:.72,roughness:.92}));back.position.set(0,y+1.45,-3.42);group.add(back);[-7.4,7.4].forEach(x=>{const edge=new THREE.Mesh(new THREE.BoxGeometry(.14,2.8,.14),new THREE.MeshStandardMaterial({color:darkScene?0x78999d:0x71858b}));edge.position.set(x,y+1.42,-3.35);group.add(edge);});const tag=document.createElement('div');tag.className='floor-label';tag.innerHTML=`<b>${floor}F</b><span>${floor} 层</span>`;const label=new CSS2DObject(tag);label.position.set(-8.2,y+.42,0);group.add(label);scene.add(group);floorObjects.set(floor,group);}const roof=new THREE.Mesh(new THREE.BoxGeometry(15,.12,7),new THREE.MeshStandardMaterial({color:darkScene?0x526d71:0xb9c8cb,transparent:true,opacity:.5}));roof.position.y=(maxFloor-1)*3.2+2.95;scene.add(roof);}
function addRoom(){if(!scene)return;const wall=new THREE.MeshStandardMaterial({color:darkScene?0x2a3b3e:0xf8fbfb,roughness:.9}),bench=new THREE.MeshStandardMaterial({color:darkScene?0x52686d:0x52666c,roughness:.55}),cabinet=new THREE.MeshStandardMaterial({color:darkScene?0x6e858a:0x789097,roughness:.65});const box=(w:number,h:number,d:number,x:number,y:number,z:number,material:THREE.Material)=>{const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;scene!.add(mesh);};box(24,3.2,.18,0,1.6,-8.9,wall);box(.18,3.2,18,-11.9,1.6,0,wall);box(.18,3.2,18,11.9,1.6,0,wall);[-3.5,0,3.5].forEach(z=>box(15,.65,1.9,0,.36,z,bench));[-7.8,7.8].forEach(x=>box(2.2,.85,5.2,x,.45,2.5,cabinet));}

function colorFor(status:string){return status==='normal'?0x15977f:status==='repair'||status==='repairing'?0xe1a12d:status==='stopped'?0x7f8d92:0x8370a7;}
function applyVisibility(){const ids=new Set(filteredNodes.value.map(x=>x.id));meshes.forEach((mesh,id)=>mesh.visible=ids.has(id));floorObjects.forEach((object,floor)=>object.visible=!floorFilter.value||floor===floorFilter.value);if(floorFilter.value&&camera&&controls&&!currentRoom.value){const y=(floorFilter.value-1)*3.2;controls.target.set(0,y+.7,0);camera.position.set(12,y+7,15);controls.update();}}
async function focusSearch(){const node=filteredNodes.value[0];if(!node)return;if(node.floor&&!currentRoom.value)floorFilter.value=node.floor;await nextTick();focusNode(node);}
function selectNode(node:Lab3dNode){if(node.type==='room'){const room=spatialLabs.value.flatMap(x=>x.rooms).find(x=>x.id===node.id);if(room){enterRoom(room);return;}}focusNode(node);}
function focusNode(node:Lab3dNode){selected.value=node;if(camera&&controls){controls.target.set(node.x,node.y,node.z);camera.position.set(node.x+5,node.y+4,node.z+6);controls.update();}}
function pick(event:PointerEvent){if(!renderer||!camera)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects([...meshes.values()].filter(x=>x.visible))[0],node=nodes.value.find(x=>x.id===hit?.object.userData.nodeId);if(node)selectNode(node);}
function resetCamera(){if(!camera||!controls)return;if(!currentRoom.value&&spatialLabs.value.length){camera.position.set(15,12,19);controls.target.set(0,3.4,0);}else{camera.position.set(11,10,14);controls.target.set(0,0,0);}controls.update();}
function animate(){frame=requestAnimationFrame(animate);controls?.update();if(scene&&camera){renderer?.render(scene,camera);labelRenderer?.render(scene,camera);}}
function resize(){const host=canvasHost.value;if(!host||!renderer||!camera)return;camera.aspect=host.clientWidth/Math.max(host.clientHeight,1);camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight);labelRenderer?.setSize(host.clientWidth,host.clientHeight);}
async function refreshStatuses(){if(!sceneId.value||demoMode.value||!spatialLabs.value.length)return;try{const states=await visualizationApi.spatialStatuses(sceneId.value);for(const state of states){const node=nodes.value.find(x=>x.id===state.nodeId);if(!node)continue;Object.assign(node,{status:state.status,detail:state.detail,upcomingBookingCount:state.upcomingBookingCount,repairingInstrumentCount:state.repairingInstrumentCount,nextBookingTime:state.nextBookingTime});const material=meshes.get(node.id)?.material as THREE.MeshStandardMaterial|undefined;material?.color.setHex(colorFor(state.status));}applyVisibility();}catch{/* 保留当前场景，下一轮自动重试。 */}}
function nodeSummary(node:Lab3dNode){return node.type==='room'?`${node.upcomingBookingCount||0} 个预约 · ${node.repairingInstrumentCount||0} 台维修`:statusText[node.status]||node.status;}
function formatTime(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false});}
function formatShortTime(value:string){return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function escapeHtml(value:string){const el=document.createElement('span');el.textContent=value;return el.innerHTML;}
async function toggleFullscreen(){document.fullscreenElement?await document.exitFullscreen():await shell.value?.requestFullscreen();await nextTick();window.setTimeout(resize,80);}
function disposeRenderer(){cancelAnimationFrame(frame);window.removeEventListener('resize',resize);controls?.dispose();scene?.traverse(object=>{const mesh=object as THREE.Mesh;mesh.geometry?.dispose();if(mesh.material)(Array.isArray(mesh.material)?mesh.material:[mesh.material]).forEach(x=>x.dispose());});renderer?.dispose();renderer?.domElement.remove();labelRenderer?.domElement.remove();floorObjects.clear();renderer=undefined;labelRenderer=undefined;scene=undefined;camera=undefined;controls=undefined;}
function dispose(){clearInterval(timer);disposeRenderer();}
</script>

